    fetch(`/api/users/${userId}`).then((r) => r.json()),
    fetch(`/api/orders?user=${userId}`).then((r) => r.json()),
    fetch(`/api/notifications?user=${userId}`).then((r) => r.json()),
  ]);
  return { profile, orders, notifications };
}

